# LIT configuration for the cq-lowering IR-pass tests.
# The site config (generated by CMake) injects CQ_OPT and CQ_PASS_PLUGIN
# into the `config` namespace before this file is loaded.

import os
import lit.formats

config.name = "CQ IR-pass"
config.test_format = lit.formats.ShTest(execute_external=True)
config.suffixes = [".ll"]
config.test_source_root = os.path.dirname(os.path.abspath(__file__))

# test_exec_root may be overridden by the site config (build-dir output).
if not getattr(config, "test_exec_root", None):
    config.test_exec_root = config.test_source_root

# Substitutions. These come in from the site config; fall back to env so
# the file remains usable when invoked without a generated site config
# (e.g. for an editor's lit-mode preview).
cq_opt = getattr(config, "cq_opt", None) or os.environ.get("CQ_OPT", "opt-19")
cq_pass = getattr(config, "cq_pass_plugin", None) or os.environ.get("CQ_PASS", "")
filecheck = getattr(config, "filecheck", None) or os.environ.get("FILECHECK", "FileCheck-19")

# %cq-opt expands to the opt binary; %cq-pass to the pass plugin path.
# Tests typically write: ; RUN: %cq-opt -load-pass-plugin %cq-pass -passes=cq-lowering -S %s | %filecheck %s
config.substitutions.append(("%cq-opt", cq_opt))
config.substitutions.append(("%cq-pass", cq_pass))
config.substitutions.append(("%filecheck", filecheck))

# Add the LLVM tools directory to PATH so bundled wrappers like `not`
# (used by negative LIT fixtures to invert opt's exit code) resolve.
# `cq_opt` is typically `/usr/lib/llvm-19/bin/opt`; the wrapper sits in
# the same directory. Falls back gracefully if `cq_opt` is a bare name.
_llvm_bin = os.path.dirname(cq_opt) if os.path.dirname(cq_opt) else ""
if _llvm_bin:
    config.environment["PATH"] = _llvm_bin + os.pathsep + os.environ.get(
        "PATH", ""
    )
